{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is each batch required to be dyed in exactly one vat (i.e., we assign each of the 5 batches to one of the 3 vats and each vat processes its assigned batches one at a time), or can a single batch be split across multiple vats?"
  ],
  "rationale": "The response asks for a single policy choice regarding batch assignment (exclusive assignment vs. splitting), which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For a given batch, must it move directly from one vat to the next with no waiting (i.e., it starts in vat 2 the moment it finishes in vat 1, and starts in vat 3 the moment it finishes in vat 2), or is it allowed to wait between vats?"
  ],
  "rationale": "The response asks a single clarification question regarding whether batches must move immediately between vats or if waiting is permitted."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can a batch start in a later vat before it has finished in the earlier vat (i.e., is there any overlap allowed between a batch's stages), or must a batch fully finish in one vat before it can begin in the next?"
  ],
  "rationale": "The response asks for a single policy choice regarding whether overlap between stages is allowed or if sequential completion is required."
}

